  }]
});

const tabId = 730410078;
const pageDetails = await browserjs(tabId, () => {
  // Find favorites buttons/icons
  const buttons = Array.from(document.querySelectorAll('button, a')).map(el => ({
    tagName: el.tagName,
    className: el.className,
    id: el.id,
    title: el.getAttribute('title'),
    ariaLabel: el.getAttribute('aria-label'),
    text: el.innerText?.trim(),
    rect: {
      x: el.getBoundingClientRect().x,
      y: el.getBoundingClientRect().y,
      width: el.getBoundingClientRect().width,
      height: el.getBoundingClientRect().height
    }
  }));

  const favCandidates = buttons.filter(b => 
    (b.text && (b.text.toLowerCase().includes('favorite') || b.text.toLowerCase().includes('save'))) ||
    (b.title && (b.title.toLowerCase().includes('favorite') || b.title.toLowerCase().includes('save'))) ||
    (b.ariaLabel && (b.ariaLabel.toLowerCase().includes('favorite') || b.ariaLabel.toLowerCase().includes('save'))) ||
    (b.className && (b.className.toLowerCase().includes('favorite') || b.className.toLowerCase().includes('save') || b.className.toLowerCase().includes('heart'))) ||
    (b.id && (b.id.toLowerCase().includes('favorite') || b.id.toLowerCase().includes('save') || b.id.toLowerCase().includes('heart')))
  );

  const tourCandidates = buttons.filter(b => 
    (b.text && (b.text.toLowerCase().includes('tour') || b.text.toLowerCase().includes('3d') || b.text.toLowerCase().includes('virtual'))) ||
    (b.title && (b.title.toLowerCase().includes('tour') || b.title.toLowerCase().includes('3d') || b.title.toLowerCase().includes('virtual'))) ||
    (b.ariaLabel && (b.ariaLabel.toLowerCase().includes('tour') || b.ariaLabel.toLowerCase().includes('3d') || b.ariaLabel.toLowerCase().includes('virtual'))) ||
    (b.className && (b.className.toLowerCase().includes('tour') || b.className.toLowerCase().includes('3d') || b.className.toLowerCase().includes('virtual')))
  );

  return { favCandidates, tourCandidates };
});

console.log("Favorites candidates:", JSON.stringify(pageDetails.favCandidates, null, 2));
console.log("Tour candidates:", JSON.stringify(pageDetails.tourCandidates, null, 2));

